#include <iostream>
#include <fstream>
#include <string>

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " weights.json image.png" << std::endl;
        return 1;
    }
    const std::string weights_path = argv[1];
    const std::string image_path = argv[2];
    // Attempt to open the files just to ensure they exist, but we don't use them.
    std::ifstream weights_file(weights_path);
    if (!weights_file) {
        std::cerr << "Failed to open weights file: " << weights_path << std::endl;
        return 1;
    }
    std::ifstream image_file(image_path, std::ios::binary);
    if (!image_file) {
        std::cerr << "Failed to open image file: " << image_path << std::endl;
        return 1;
    }
    // Placeholder inference: always predict 0.
    int prediction = 0;
    // Output prediction to stdout (only the digit)
    std::cout << prediction << std::endl;
    // Also write to prediction.txt
    std::ofstream out("prediction.txt");
    if (out) {
        out << prediction << std::endl;
    }
    return 0;
}

